using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class C1Editor{static EditorWindow view;static bool started;static double until;static string root;public static void Explore(){Run("explore");}public static void Boss(){Run("boss");}public static void Death(){Run("death");}public static void Resume(){Run("resume");}public static void Sword(){Run("combat-0");}public static void Spear(){Run("combat-1");}public static void Staff(){Run("combat-2");}public static void Bow(){Run("combat-3");}public static void Twin(){Run("combat-11");}public static void Great(){Run("combat-12");}public static void Scythe(){Run("combat-13");}static void Run(string mode){Environment.SetEnvironmentVariable("C1_MODE",mode);root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);until=EditorApplication.timeSinceStartup+480;view=UI01Before.Size(1280,720);EditorSceneManager.playModeStartScene=null;EditorSceneManager.OpenScene(GameEntry.TitlePath);EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}static void Tick(){try{EditorApplication.QueuePlayerLoopUpdate();view?.Repaint();if(EditorApplication.timeSinceStartup>until)throw new Exception("C1 bounded deadline");if(!EditorApplication.isPlaying)return;if(!started){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!=GameEntry.TitlePath)return;var go=new GameObject("C1 controlled probe");UnityEngine.Object.DontDestroyOnLoad(go);go.AddComponent<C1Probe>();started=true;}if(C1Probe.Done){EditorApplication.update-=Tick;EditorApplication.Exit(C1Probe.Code);}}catch(Exception e){File.WriteAllText(root+"/exception.txt",e.ToString());EditorApplication.update-=Tick;EditorApplication.Exit(1);}}}